#!/usr/bin/env python3
"""
IP / SNI scanner - standalone, Python 3.9+, no extra packages.

Run:      python scanner.py          (opens http://127.0.0.1:8787 automatically;
          if that port is busy it picks the next free one and prints it)
Options:  --port 8787   --host 127.0.0.1   --no-open

It starts a local engine (real TCP / TLS+SNI / HTTP / WebSocket / vless+trojan
end-to-end tests over YOUR own internet connection) and serves the panel.
Keep it bound to 127.0.0.1 unless you know what you are doing.
"""
import argparse, asyncio, base64, errno, hashlib, json, os, re, socket, ssl, struct, sys, time, uuid
import urllib.request
from urllib.parse import urlparse, parse_qs

PAGE = base64.b64decode("")
SEM = None
VERSION = "v14"
STARTED = time.time()
LASTPORT = None


_CTX = None
SCAN_CAP = 400
JOB_CAP = 400
TCP_CAP = 800
JOBS = {}


def ctx():
    global _CTX
    if _CTX is None:
        c = ssl.create_default_context()
        c.check_hostname = False
        c.verify_mode = ssl.CERT_NONE
        c.set_alpn_protocols(["http/1.1"])
        _CTX = c
    return _CTX


def _mk_sock(ip):
    s = socket.socket(socket.AF_INET6 if ":" in ip else socket.AF_INET, socket.SOCK_STREAM)
    s.setblocking(False)
    try:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_LINGER, struct.pack("ii", 1, 0))
    except Exception:
        pass
    return s


async def tcp_ok(ip, port, to):
    s = None
    try:
        s = _mk_sock(ip)
        await asyncio.wait_for(asyncio.get_running_loop().sock_connect(s, (ip, port)), to)
        return True, None
    except Exception as e:
        return False, errname(e)
    finally:
        if s:
            s.close()


def netinfo():
    out = {"v4": False, "v6": False}
    for k, fam, addr in (("v4", socket.AF_INET, "1.1.1.1"), ("v6", socket.AF_INET6, "2606:4700:4700::1111")):
        s = None
        try:
            s = socket.socket(fam, socket.SOCK_DGRAM)
            s.connect((addr, 53))
            out[k] = True
        except Exception:
            pass
        finally:
            if s:
                s.close()
    return out


def errname(e):
    if isinstance(e, asyncio.TimeoutError):
        return "timeout"
    if isinstance(e, OSError) and e.errno in errno.errorcode:
        return errno.errorcode[e.errno]
    return type(e).__name__


def fetch_text(u, tok=None):
    if not u.startswith("https://"):
        return ""
    h = {"User-Agent": "scanner", "Accept": "*/*"}
    if tok and urlparse(u).hostname == "api.github.com":
        h["Authorization"] = "Bearer " + tok
    try:
        return urllib.request.urlopen(urllib.request.Request(u, headers=h), timeout=15).read(6000000).decode("utf-8", "ignore")
    except Exception:
        return ""


async def close(w):
    if w:
        try:
            w.close()
        except Exception:
            pass


async def probe(q):
    ip, port, sni = q.get("ip", ""), int(q.get("port", 0)), q.get("sni")
    to = int(q.get("t", 3000)) / 1000
    t0 = time.time()
    ms = lambda: int((time.time() - t0) * 1000)
    box = {}

    async def run():
        if not sni:
            r, box["w"] = await asyncio.open_connection(ip, port)
            return {"open": True, "tls": False}
        r, box["w"] = await asyncio.open_connection(ip, port, ssl=ctx(), server_hostname=sni)
        w = box["w"]
        so = w.get_extra_info("ssl_object")
        o = {"open": True, "tls": True, "proto": so.version(), "alpn": so.selected_alpn_protocol()}
        if q.get("http"):
            host = q.get("host") or sni
            if q.get("ws"):
                req = ("GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                       "Sec-WebSocket-Version: 13\r\nSec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
                       "User-Agent: Mozilla/5.0\r\n\r\n" % (q.get("path") or "/", host))
            else:
                req = ("GET / HTTP/1.1\r\nHost: %s\r\nUser-Agent: Mozilla/5.0\r\n"
                       "Connection: close\r\n\r\n" % host)
            w.write(req.encode())
            await w.drain()
            d = await r.read(2048)
            o["lat"] = ms()
            m = re.match(rb"HTTP/\d\.\d (\d+)", d)
            o["http"] = int(m.group(1)) if m else 0
            sv = re.search(rb"\r\nserver: ([^\r\n]+)", d, re.I)
            o["server"] = sv.group(1).decode("latin1") if sv else ""
            rm = re.search(rb"\r\ncf-ray: ([^\r\n]+)", d, re.I)
            o["ray"] = rm.group(1).decode("latin1") if rm else ""
            o["cf"] = bool(rm) or o["server"].lower().startswith("cloudflare")
            if o["http"] == 101:
                try:
                    x = await asyncio.wait_for(r.read(1), float(q.get("hold", 1500)) / 1000)
                    o["stable"] = x != b""
                except asyncio.TimeoutError:
                    o["stable"] = True
        return o

    try:
        res = await asyncio.wait_for(run(), to + 2)
    except Exception as e:
        res = {"open": False, "err": errname(e)}
    await close(box.get("w"))
    res["ms"] = ms()
    return res


def wsframe(b):
    m, n = os.urandom(4), len(b)
    h = bytes([0x82, 0x80 | n]) if n < 126 else bytes([0x82, 0xFE]) + struct.pack(">H", n)
    return h + m + bytes(c ^ m[i % 4] for i, c in enumerate(b))


def wsparse(buf, out):
    while len(buf) >= 2:
        l, o = buf[1] & 127, 2
        if l == 126:
            if len(buf) < 4:
                break
            l, o = struct.unpack(">H", buf[2:4])[0], 4
        elif l == 127:
            if len(buf) < 10:
                break
            l, o = struct.unpack(">Q", buf[2:10])[0], 10
        if len(buf) < o + l:
            break
        if buf[0] & 15 in (1, 2):
            out += buf[o:o + l]
        buf = buf[o + l:]
    return buf, out


async def e2e(q):
    t0 = time.time()
    to = float(q.get("t", 6000)) / 1000
    ws, pr = q.get("net") == "ws", q.get("proto")
    th = q.get("th", "cp.cloudflare.com")
    H = th.encode()
    try:
        tp = int(q.get("tp", 80))
        want = int(q.get("bytes", 0))
    except ValueError:
        return {"ok": False, "err": "bad-params"}
    tpath = q.get("tpath", "/generate_204")
    req = ("GET %s HTTP/1.1\r\nHost: %s\r\nUser-Agent: Mozilla/5.0\r\nConnection: close\r\n\r\n"
           % (tpath, th)).encode()
    try:
        if pr == "vless":
            pl = (b"\x00" + uuid.UUID(q["id"]).bytes + b"\x00\x01" + struct.pack(">H", tp)
                  + b"\x02" + bytes([len(H)]) + H + req)
        else:
            pl = (hashlib.sha224(q["id"].encode()).hexdigest().encode() + b"\r\n\x01\x03"
                  + bytes([len(H)]) + H + struct.pack(">H", tp) + b"\r\n" + req)
    except Exception:
        return {"ok": False, "err": "bad-id"}
    box = {}

    async def run():
        r, box["w"] = await asyncio.open_connection(q["ip"], int(q["port"]), ssl=ctx(), server_hostname=q["sni"])
        w = box["w"]
        if ws:
            key = base64.b64encode(os.urandom(16)).decode()
            w.write(("GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
                     "Sec-WebSocket-Version: 13\r\nSec-WebSocket-Key: %s\r\nUser-Agent: Mozilla/5.0\r\n\r\n"
                     % (q.get("path") or "/", q.get("host") or q["sni"], key)).encode())
            hd = await r.readuntil(b"\r\n\r\n")
            if not hd.startswith(b"HTTP/1.1 101"):
                return {"ok": False, "err": "ws-" + hd[9:12].decode("latin1")}
            w.write(wsframe(pl))
        else:
            w.write(pl)
        buf = out = b""
        status = tfirst = None
        while True:
            if tfirst is not None:
                left = 5.0 - (time.time() - tfirst)
                if left <= 0:
                    break
                try:
                    d = await asyncio.wait_for(r.read(65536), left)
                except asyncio.TimeoutError:
                    break
            else:
                d = await r.read(4096)
            if not d:
                break
            if ws:
                buf, out = wsparse(buf + d, out)
            else:
                out += d
            o = out
            if pr == "vless":
                if len(o) < 2:
                    continue
                o = o[2 + o[1]:]
            if status is None and len(o) >= 12:
                m = re.match(rb"HTTP/1\.[01] (\d+)", o)
                if not m:
                    return {"ok": False, "err": "bad-response"}
                status, tfirst = int(m.group(1)), time.time()
                if not want:
                    return {"ok": True, "http": status}
                if not 200 <= status < 300:
                    return {"ok": False, "err": "http-%d" % status}
            if want and status is not None and len(o) >= want:
                break
        if status is None:
            return {"ok": False, "err": "closed"}
        o = out[2 + out[1]:] if pr == "vless" and len(out) >= 2 else out
        dt = max(time.time() - tfirst, 0.001)
        return {"ok": True, "http": status, "bytes": len(o), "kbps": round(len(o) / 1024 / dt, 1)}

    try:
        res = await asyncio.wait_for(run(), to)
    except Exception as e:
        res = {"ok": False, "err": errname(e)}
    await close(box.get("w"))
    res["ms"] = int((time.time() - t0) * 1000)
    return res


def parse_ports(s):
    if s == "all":
        return list(range(1, 65536))
    out = set()
    for x in s.split(","):
        m = re.fullmatch(r"(\d+)(?:-(\d+))?", x.strip())
        if m:
            out.update(range(int(m[1]), min(int(m[2] or m[1]), 65535) + 1))
    return sorted(out)


async def scan_ports(q):
    ip, ps = q.get("ip", ""), parse_ports(q.get("ports", "all"))
    to, c = int(q.get("t", 900)) / 1000, max(1, min(int(q.get("c", 500)), TCP_CAP))
    found, errs, it = [], {}, iter(ps)

    async def worker():
        for p in it:
            ok, er = await tcp_ok(ip, p, to)
            if ok:
                found.append(p)
            else:
                errs[er] = errs.get(er, 0) + 1

    await asyncio.gather(*(worker() for _ in range(c)))
    return {"open": sorted(found), "errs": errs, "c": c}


async def batch(q):
    jobs = [j.split("|") for j in q.get("jobs", "").split(";") if j]

    async def one(j):
        async with SEM:
            qq = dict(q)
            qq["ip"], qq["port"] = j[0], j[1]
            return await probe(qq)

    return await asyncio.gather(*(one(j) for j in jobs))


async def verify_one(q, ip, port):
    base = dict(q)
    base["ip"], base["port"] = ip, port
    if q.get("mode") == "extra":
        out = {}
        x = await e2e(dict(base, t=14000, bytes=1000000))
        out["kbps"] = x.get("kbps") if x.get("ok") else None
        plain = {k: v for k, v in base.items() if k not in ("th", "tp", "tpath", "bytes")}
        rs = await asyncio.gather(*(e2e(dict(plain, t=8000)) for _ in range(4)))
        out["par"] = sum(1 for r in rs if r.get("ok"))
        return out
    ms, errs = [], []
    for _ in range(3):
        x = await e2e(dict(base, t=8000))
        if x.get("ok"):
            ms.append(x["ms"])
        else:
            errs.append(x.get("err", "x"))
    return {"ms": ms, "errs": errs}


async def job_worker(job, it, kind, params):
    for i, x in it:
        if job["cancel"]:
            return
        try:
            if kind == "tcp":
                t0 = time.time()
                ok, er = await tcp_ok(x[0], int(x[1]), float(params.get("t", 1000)) / 1000)
                res = {"open": ok, "err": er, "ms": int((time.time() - t0) * 1000)}
            elif kind == "probe":
                q = dict(params)
                q["ip"], q["port"] = x[0], x[1]
                res = await probe(q)
            else:
                res = await verify_one(params, x[0], x[1])
        except Exception as e:
            res = {"open": False, "err": errname(e)}
        job["res"].append([i, res])
        job["done"] += 1


async def run_job(job, kind, items, params, conc):
    it = iter(enumerate(items))
    await asyncio.gather(*(job_worker(job, it, kind, params) for _ in range(conc)))
    job["finished"] = True


def job_start(body):
    d = json.loads(body.decode("utf-8"))
    kind, items, params = d.get("kind"), d.get("items") or [], d.get("params") or {}
    if kind not in ("probe", "verify", "tcp") or len(items) > 300000:
        return {"err": "bad-job"}
    cap = TCP_CAP if kind == "tcp" else JOB_CAP if kind == "probe" else 16
    conc = max(1, min(int(d.get("conc", 200)), cap, max(1, len(items))))
    jid = uuid.uuid4().hex[:12]
    job = {"res": [], "done": 0, "total": len(items), "finished": False, "cancel": False, "t": time.time()}
    JOBS[jid] = job
    for k in sorted(JOBS, key=lambda z: JOBS[z]["t"])[:-12]:
        if JOBS[k]["finished"] or JOBS[k]["cancel"]:
            JOBS.pop(k, None)
    job["task"] = asyncio.ensure_future(run_job(job, kind, items, params, conc))
    return {"id": jid, "conc": conc}


def job_poll(q):
    j = JOBS.get(q.get("id", ""))
    if not j:
        return {"err": "nojob"}
    a = int(q.get("from", 0))
    return {"done": j["done"], "total": j["total"], "finished": j["finished"], "res": j["res"][a:a + 4000]}


async def handle(r, w):
    try:
        line = await asyncio.wait_for(r.readline(), 10)
        clen = 0
        while True:
            hl = await asyncio.wait_for(r.readline(), 10)
            if hl in (b"\r\n", b"\n", b""):
                break
            if hl.lower().startswith(b"content-length:"):
                clen = min(int(hl.split(b":")[1]), 8000000)
        rbody = await asyncio.wait_for(r.readexactly(clen), 30) if clen else b""
        if line.startswith(b"OPTIONS"):
            w.write(b"HTTP/1.1 204 No Content\r\nAccess-Control-Allow-Origin: *\r\n"
                    b"Access-Control-Allow-Private-Network: true\r\nAccess-Control-Allow-Headers: *\r\n"
                    b"Access-Control-Allow-Methods: GET, POST, OPTIONS\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
            await w.drain()
            return
        u = urlparse(line.decode("latin1").split(" ")[1])
        q = {k: v[0] for k, v in parse_qs(u.query).items()}
        ct = b"application/json"
        if u.path == "/":
            body, ct = PAGE, b"text/html; charset=utf-8"
        elif u.path == "/ping":
            body, ct = ("ok %s %d" % (VERSION, int(time.time() - STARTED))).encode(), b"text/plain"
        elif u.path == "/fetch":
            body, ct = (await asyncio.to_thread(fetch_text, q.get("url", ""), q.get("gh"))).encode(), b"text/plain; charset=utf-8"
        elif u.path == "/job/start":
            body = json.dumps(job_start(rbody)).encode()
        elif u.path == "/job/poll":
            body = json.dumps(job_poll(q)).encode()
        elif u.path == "/job/cancel":
            if q.get("id") in JOBS:
                JOBS[q["id"]]["cancel"] = True
            body = b"{}"
        elif u.path == "/net":
            body = json.dumps(netinfo()).encode()
        elif u.path == "/ports":
            body = json.dumps(await scan_ports(q)).encode()
        elif u.path == "/batch":
            body = json.dumps(await batch(q)).encode()
        elif u.path == "/e2e":
            async with SEM:
                body = json.dumps(await e2e(q)).encode()
        else:
            async with SEM:
                body = json.dumps(await probe(q)).encode()
        w.write(b"HTTP/1.1 200 OK\r\nAccess-Control-Allow-Origin: *\r\nAccess-Control-Allow-Private-Network: true\r\n"
                b"Cache-Control: no-store\r\nContent-Type: " + ct + b"\r\nContent-Length: "
                + str(len(body)).encode() + b"\r\nConnection: close\r\n\r\n" + body)
        await w.drain()
    except Exception:
        pass
    finally:
        await close(w)


async def main(host, port, openb):
    global SEM, SCAN_CAP, JOB_CAP, TCP_CAP, LASTPORT
    asyncio.get_running_loop().set_exception_handler(lambda loop, ctx: None)
    soft = 1024
    try:
        import resource
        s, h = resource.getrlimit(resource.RLIMIT_NOFILE)
        want = 8192 if h == resource.RLIM_INFINITY else min(h, 8192)
        if s < want:
            resource.setrlimit(resource.RLIMIT_NOFILE, (want, h))
        soft = resource.getrlimit(resource.RLIMIT_NOFILE)[0]
    except Exception:
        pass
    fdmax = max(200, soft - 250)
    SEM = asyncio.Semaphore(max(100, min(600, fdmax // 2)))
    SCAN_CAP = max(100, min(800, fdmax // 3))
    JOB_CAP = SCAN_CAP
    TCP_CAP = max(200, min(1500, int(fdmax * 0.6)))
    srv = None
    for p in range(port, port + 20):
        try:
            srv = await asyncio.start_server(handle, host, p, backlog=1024)
            port = p
            break
        except OSError:
            continue
    if not srv:
        sys.exit("No free port found near %d. Close other scanners and try again." % port)
    global PAGE
    # the panel talks to 127.0.0.1:8787 - point it at the port we really got
    PAGE = PAGE.replace(b"127.0.0.1:8787", ("127.0.0.1:%d" % port).encode())
    LASTPORT = port
    url = "http://%s:%d" % (host, port)
    print("If it keeps dying: Android Settings > Apps > this app > Battery > Unrestricted")
    print("scanner", VERSION, "ready ->", url, "  (Ctrl+C to stop)")
    if openb:
        import webbrowser
        webbrowser.open(url)
    async with srv:
        await srv.serve_forever()


def run_forever(host, port, openb):
    """supervisor: if the engine ever crashes, restart it on the SAME port"""
    first = True
    while True:
        try:
            asyncio.run(main(host, LASTPORT or port, openb and first))
            return
        except KeyboardInterrupt:
            print("\nstopped")
            return
        except Exception as e:
            print("engine error, restarting in 1s:", repr(e))
            first = False
            time.sleep(1)


if __name__ == "__main__":
    ap = argparse.ArgumentParser(description="IP/SNI scanner with local panel")
    ap.add_argument("--host", default="127.0.0.1")
    ap.add_argument("--port", type=int, default=8787)
    ap.add_argument("--open", action="store_true", help=argparse.SUPPRESS)
    ap.add_argument("--no-open", action="store_true", help="do not open the browser automatically")
    a = ap.parse_args()
    run_forever(a.host, a.port, not a.no_open)
